ee:message.ee:set-payload:
%dw 2.0 output application/json
var accountId = (payload.account_id default "") as String var clientId = (payload.client_id default "") as String var customerId = (payload.customer_id default "") as String
--- { account_id: accountId, customer_id: customerId, client_id: clientId, plan_type: payload.plan_type default "", plan_name: payload.plan_name default "", balance: payload.balance default null, settled_balance: payload.settled_balance default null, vested_balance: payload.vested_balance default null, available_for_withdrawal: payload.available_for_withdrawal default null, currency: payload.currency default "", status: payload.status default "", tax_year: payload.tax_year default null, account_id_valid: accountId matches /^A[0-9]{4}$/, customer_id_valid: customerId matches /^C[0-9]{4}$/, client_id_valid: clientId matches /^C[0-9]{4}$/ }
